const j = $json;
// find a column by partial header text, so small title edits don't break the flow
const get = (key) => {
  const k = Object.keys(j).find(c => c.toLowerCase().includes(key));
  return k ? String(j[k] ?? '').trim() : '';
};

const name  = get('full name');
const email = get('email').toLowerCase();
const phone = get('phone').replace(/[\s\-+]/g, '').replace(/^91(?=\d{10}$)/, '');
const notes = get('additional');
const mode  = get('mode of learning');
const source = get('hear about us');

// course -> canonical value
const c = get('which course').toLowerCase();
const course = c.includes('web') ? 'Web Development Bootcamp'
  : c.includes('data science') ? 'Data Science and Machine Learning'
  : c.includes('business') ? 'Business Analytics'
  : c.includes('ai engineer') ? 'AI Engineer' : '';

// experience -> canonical value
const e = get('level of experience').toLowerCase();
const experience = e.includes('beginner') ? 'Complete Beginner'
  : e.includes('basic') ? 'Some Basic Knowledge'
  : e.includes('intermediate') ? 'Intermediate'
  : e.includes('advanced') ? 'Advanced' : '';

// start timeline -> months (4 = more than 3, 99 = just exploring)
const s = get('planning to start').toLowerCase();
const m = s.match(/within\s+(\d)\s+month/);
const startMonths = m ? parseInt(m[1]) : s.includes('more than') ? 4 : s.includes('explor') ? 99 : null;
const startLabel = startMonths === null ? '' : startMonths <= 3 ? `Within ${startMonths} Month${startMonths > 1 ? 's' : ''}`
  : startMonths === 4 ? 'More Than 3 Months' : 'Just Exploring';

// timestamp: handles month/day/year (US sheet) and day/month/year (first number > 12)
// stored as local IST time with an explicit +05:30 offset
const pad = (n) => String(n).padStart(2, '0');
const p = get('timestamp').match(/(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2}):(\d{2})/);
let submitted_at = new Date().toISOString();
if (p) {
  const a = +p[1], b = +p[2];
  const day = a > 12 ? a : b;
  const month = a > 12 ? b : a;
  submitted_at = `${p[3]}-${pad(month)}-${pad(day)}T${pad(p[4])}:${p[5]}:${p[6]}+05:30`;
}

// validation
const errors = [];
if (!name) errors.push('missing name');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) errors.push('invalid email');
if (!/^[6-9]\d{9}$/.test(phone)) errors.push('invalid phone');
if (!course) errors.push('unknown course');
if (!experience) errors.push('unknown experience');
if (startMonths === null) errors.push('unknown start timeline');

return { json: {
  lead_id: 'LD-' + Date.now().toString(36).toUpperCase() + '-' + $itemIndex,
  submitted_at, name, email, phone, course,
  learning_mode: mode, experience_level: experience,
  start_timeline: startLabel, start_months: startMonths,
  source, notes,
  is_valid: errors.length === 0,
  validation_errors: errors.join('; ')
}};
